sp_widget.client_script:
api.controller=function($scope, $window) {
    var c = this;

    // Mapeamento: sys_id do Card -> ID da Página de Destino no Service Portal
    // ATENÇÃO: Você deve ajustar o 'nome_da_pagina_detalhe' para a página que você criou
    c.detailPages = {
        'rankingCLP': 'nome_da_pagina_detalhe', 
        'capacidadePE': 'nome_da_pagina_detalhe',
        'programaAF': 'nome_da_pagina_detalhe',
        'limiteEndividamento': 'nome_da_pagina_detalhe',
        'superavit': 'nome_da_pagina_detalhe',
        'investimentoRCL': 'nome_da_pagina_detalhe'
    };

    // A função é chamada ao clicar no botão "Detalhar"
    c.detalhar = function(card) {
        var pageId = c.detailPages[card.sys_id];

        if (pageId) {
            // Constrói o URL: ?id=<pageId>&sys_id=<sys_id_do_card>
            var url = "?id=" + pageId + "&sys_id=" + card.sys_id;

            // Abre em uma nova aba, como solicitado
            $window.open(url, '_blank');
        } else {
            console.error("Página de destino não configurada para o card:", card.title);
            alert("Detalhes não disponíveis no momento. Verifique o mapeamento no Client Script.");
        }
    };

    // Opcional: Se a função no HTML for openDetail, renomeie aqui:
    c.openDetail = c.detalhar; 
}

sp_widget.css:
/* Container Principal */
.widget-container {
    max-width: 1200px;
    margin: auto;
    padding: 20px;
    background-color: white;
}

/* 1. Estilos do Título Principal */
.main-title {
    font-family: 'Roboto', sans-serif;
    font-weight: 700;
    font-size: 42px;
    line-height: 100%;
    color: #4671C4;
    margin-bottom: 40px;
    padding: 10px 0;
}

/* === REGRAS BASE (TODAS AS TELAS E DESKTOP: 3 CARDS) === */
.card-row {
    display: flex;
    /* Adicionamos 'flex-wrap: wrap' aqui para garantir a quebra do 4º card no desktop */
    flex-wrap: wrap; 
    justify-content: space-between;
    align-items: stretch;
    margin-bottom: 20px; /* Garante espaço entre a linha de cima e a de baixo */
}

.card-wrapper {
    /* Largura para 3 cards por linha */
    width: 32.5%; 
    padding: 0;
    /* Adiciona margem inferior para o espaçamento vertical entre as linhas (3x3) */
    margin-bottom: 20px;
}

.index-card {
    border: none;
    border-radius: 8px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    padding: 15px;
    height: 100%;
    display: flex;
    flex-direction: column;
}

.card-title-index {
    font-size: 18px;
    font-weight: bold;
    color: #4671C4;
    text-align: center;
    margin-bottom: 25px; 
}

.chart-image-placeholder {
    flex-grow: 1; 
    border: 1px solid #eee;
    height: 180px; 
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 20px;
}

.chart-image {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
    display: block;
}

.text-end {
    display: flex;
    justify-content: flex-end;
    width: 100%;
    margin-top: 0;
}

.btn-detalhar {
    background-color: transparent;
    border: 1px solid #4671C4;
    color: #4671C4;
    font-weight: 600;
    padding: 5px 15px;
    border-radius: 4px;
    transition: all 0.3s ease;
    cursor: pointer;
}

.btn-detalhar:hover {
    background-color: #4671C4;
    color: #ffffff;
    transform: translateY(-5px);
    box-shadow: 0 8px 15px rgba(0, 0, 0, 0.15);
}

/* === MEDIA QUERY PARA TELAS MÉDIAS (2 CARDS) === */
@media (max-width: 991px) {
    .card-wrapper {
        /* 2 cards por linha */
        width: 48%; 
        /* Mantemos o margin-bottom: 20px do CSS base */
    }

    .card-row {
        /* Centraliza os cards quando há ímpar (ex: 5 cards quebram para 2 + 2 + 1) */
        justify-content: space-around; 
    }
}

/* === MEDIA QUERY PARA TELAS PEQUENAS (1 CARD) === */
@media (max-width: 767px) {
    .main-title {
        font-size: 30px; 
    }

    .card-wrapper {
        /* 1 card por linha */
        width: 95%; 
        margin: 0 auto 20px auto; 
    }

    .card-row {
        justify-content: center; 
    }
}

